import { escapeHtml as h } from './domain.js';
export function galaxyView(signals, selectedId, zoom){
  const selected=signals.find(p=>p.id===selectedId);
  const label=p=>`${p.designation}${p.clan_name?` [${p.clan_name}]`:''}`;
  return `<section class="galaxy"><div class="galaxy-toolbar"><div class="map-legend"><span><i class="own-dot"></i>Vos mondes</span><span><i class="clan-dot"></i>Tag public</span><span><i></i>Non identifié</span></div><div class="map-zoom"><button data-zoom="-1" ${zoom<=1?'disabled':''} aria-label="Réduire la carte">−</button><span>${Math.round(zoom*100)} %</span><button data-zoom="1" ${zoom>=3?'disabled':''} aria-label="Agrandir la carte">+</button></div></div><div class="galaxy-body"><div class="galaxy-scroll" tabindex="0" aria-label="Carte galactique, faites défiler pour explorer"><svg class="galaxy-svg" style="width:${zoom*100}%;min-width:${zoom*440}px" viewBox="-45 -45 1090 1090" role="img" aria-label="Positions des mondes de la session"><defs><radialGradient id="nebula"><stop stop-color="#326e8a" stop-opacity=".26"/><stop offset="1" stop-color="#080e18" stop-opacity="0"/></radialGradient><pattern id="mapgrid" width="100" height="100" patternUnits="userSpaceOnUse"><path d="M100 0H0V100" fill="none" stroke="#8aa8b4" stroke-opacity=".09" stroke-width="1"/></pattern></defs><rect x="-45" y="-45" width="1090" height="1090" fill="#080f1a"/><ellipse cx="450" cy="470" rx="650" ry="430" fill="url(#nebula)" transform="rotate(-30 450 470)"/><rect width="1000" height="1000" fill="url(#mapgrid)"/>${[0,200,400,600,800,1000].map(n=>`<text x="${n}" y="-15" class="map-coordinate">${n}</text><text x="-35" y="${n+4}" class="map-coordinate">${n}</text>`).join('')}${signals.map(p=>`<g class="map-signal ${p.is_own?'is-own':p.clan_name?'is-tagged':''} ${selectedId===p.id?'is-selected':''}" data-signal="${h(p.id)}" transform="translate(${p.x},${p.y})"><title>${h(label(p))}</title><circle class="signal-halo" r="15"/><circle class="signal-core" r="${p.is_own?5:3.5}"/>${p.is_own||p.clan_name||selectedId===p.id?`<text x="${p.x>730?-12:12}" y="-8" text-anchor="${p.x>730?'end':'start'}">${h(p.designation)}</text>${p.clan_name?`<text class="signal-tag" x="${p.x>730?-12:12}" y="8" text-anchor="${p.x>730?'end':'start'}">[${h(p.clan_name)}]</text>`:''}`:''}</g>`).join('')}</svg></div><aside class="signal-info"><div class="eyebrow">OBSERVATOIRE GALACTIQUE</div><h2>Un ciel,<br>mille intentions.</h2><label class="field">Sélectionner un signal<select id="signal-select">${signals.map(p=>`<option value="${h(p.id)}" ${selectedId===p.id?'selected':''}>${h(label(p))}</option>`).join('')}</select></label>${selected?`<div class="signal-readout"><span class="eyebrow">${selected.is_own?'VOTRE PLANÈTE':selected.clan_name?'SIGNATURE PUBLIQUE':'SIGNAL NON IDENTIFIÉ'}</span><h3>${h(selected.designation)}</h3>${selected.clan_name?`<strong class="public-clan-tag">[${h(selected.clan_name)}]</strong>`:'<p>Aucun tag de clan public.</p>'}<div class="signal-coords">X ${Math.round(selected.x)} <span>·</span> Y ${Math.round(selected.y)}</div><p>${selected.is_own?'Vos informations détaillées sont disponibles dans la page Planètes.':'Propriétaire, population, race, ressources et forces restent inconnus. Un tag public déclare une affiliation sans révéler le propriétaire.'}</p>${selected.is_own?`<button class="secondary" data-open-planet="${h(selected.id)}">Gérer cette planète →</button>`:''}</div>`:''}<p class="form-note">Les positions sont publiques. Les mondes extérieurs sans tag restent des signaux anonymes. La reconnaissance sera ajoutée avec les flottes.</p></aside></div></section>`;
}
